"""Code-native local control room UI."""

PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>dopOS local control room</title>
<style>
:root{--bg:#07101f;--panel:#0b1328;--line:#26365a;--muted:#9aa7c7;--text:#f3f6ff;--blue:#4c82ff;--violet:#7a3cff;--ok:#75e6a2;--danger:#ff697f}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 45% 15%,#172d5d 0,#08111f 37%,#040914 100%);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;min-height:100vh}.shell{max-width:1520px;margin:auto;padding:20px 28px}.top{height:52px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #1e2c4c}.brand{font-size:31px;font-weight:650;letter-spacing:-1.7px}.clock{color:#dce4fb;font-size:15px}.tools{display:flex;gap:18px;color:#cad4ec;font-size:14px}.tools span:before{content:'●';color:var(--ok);font-size:11px;margin-right:7px}.tools .status-off:before{color:#ff9aa8}.tools .status-off{color:#a7adc0}.frame{display:grid;grid-template-columns:minmax(0,2.45fr) minmax(330px,1fr);min-height:calc(100vh - 94px);border:1px solid #1e3154;border-radius:17px;overflow:hidden;background:#07101ee8;box-shadow:0 30px 100px #0008}.conversation{padding:42px clamp(28px,8vw,140px) 30px;display:flex;flex-direction:column;gap:26px}.thread{display:flex;flex-direction:column;gap:25px;min-height:390px}.message{max-width:82%;font-size:17px;line-height:1.56}.message.user{align-self:flex-end;background:linear-gradient(135deg,#1d3158,#162442);padding:20px 24px;border-radius:16px 16px 4px 16px}.agent{display:grid;grid-template-columns:112px 1fr;gap:20px;align-items:start}.orb{width:86px;height:86px;border:2px solid #714bff;border-radius:50%;display:grid;place-items:center;box-shadow:0 0 36px #653cdd6b;color:#a890ff;font-size:37px}.orb:after{content:'⌁';transform:rotate(-10deg)}.label{color:#8e73ff;font-weight:700}.time{color:var(--muted);font-size:13px;margin-left:12px}.explain{margin:7px 0;color:#e7ecfb}.plan{border:1px solid #6947d2;border-radius:15px;background:#0b1428;padding:19px 20px;box-shadow:inset 2px 0 #7c42ff}.plan h3{margin:0 0 7px;font-size:17px}.plan p{margin:0 0 13px;color:#c3cee7}.actions{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:15px}.actions span{font:12px ui-monospace,SFMono-Regular,monospace;color:#a9c2ff;border:1px solid #2d4777;border-radius:6px;padding:5px 7px}.buttons{display:flex;gap:10px}.button{border:1px solid #52648b;border-radius:9px;background:#17213a;color:white;padding:11px 20px;font:600 15px inherit;cursor:pointer}.button.primary{border-color:#6a68ff;background:linear-gradient(135deg,#3278fa,#7d38e5)}.button.danger{color:#ff9aa8;border-color:#9f4052;background:#251520}.composer{border:1px solid #386df3;border-radius:15px;padding:8px 9px 8px 17px;background:#071327;display:flex;gap:12px;align-items:center;box-shadow:0 0 20px #284fc824}.composer textarea{resize:none;flex:1;min-height:46px;border:0;outline:0;background:transparent;color:white;font:16px inherit;padding:12px 0}.send{width:44px;height:44px;border:0;border-radius:12px;background:#25468f;color:white;font-size:24px;cursor:pointer}.hint{font-size:12px;color:var(--muted);padding-left:5px}.rail{border-left:1px solid #1d2c4a;padding:31px;background:#0914269c}.rail h2{margin:0;font-size:22px}.rail-head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #1f304e;padding-bottom:21px}.pulse{font-size:29px;color:#8a5dff}.steps{padding:20px 0 24px;border-bottom:1px solid #1f304e}.step{position:relative;padding:0 0 21px 44px;color:#aeb9d1}.step:last-child{padding-bottom:0}.step:before{content:'';position:absolute;left:10px;top:6px;width:15px;height:15px;border:2px solid #8090b1;border-radius:50%;background:#101a2c}.step:after{content:'';position:absolute;left:17px;top:24px;height:30px;border-left:1px solid #4d5d7b}.step:last-child:after{display:none}.step.active{color:white}.step.active:before{border-color:#5790ff;background:#275ed6;box-shadow:0 0 14px #3679ff}.step strong{display:block;font-size:15px}.step small{font-size:13px;color:var(--muted)}.side-section{padding-top:25px}.side-section h3{font-size:18px;margin:0 0 17px}.history-item{display:block;width:100%;text-align:left;border:1px solid #263b63;border-radius:9px;background:#0c1830;color:#e8edfc;padding:10px 12px;margin:0 0 8px;cursor:pointer;font:inherit}.history-item:hover{border-color:#637ff3;background:#101f3d}.history-item strong{display:block;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.history-item small{display:block;color:#9eadca;margin-top:3px;text-transform:capitalize}.event{position:relative;padding:0 0 16px 23px;color:#bec8e0;font-size:14px}.event:before{content:'';position:absolute;left:3px;top:6px;width:7px;height:7px;border-radius:50%;background:#91a0cc}.event time{display:block;color:#7785a9;font-size:12px;margin-top:3px}.empty{color:var(--muted);font-size:15px;text-align:center;padding:28px 10px}@media(max-width:900px){.shell{padding:12px}.top{height:auto;gap:12px;flex-wrap:wrap;padding-bottom:12px}.tools{order:3;width:100%;justify-content:space-between;gap:5px}.frame{grid-template-columns:1fr}.rail{border-left:0;border-top:1px solid #1d2c4a}.conversation{padding:28px 20px}.message{max-width:95%}.agent{grid-template-columns:64px 1fr}.orb{width:55px;height:55px;font-size:24px}.clock{font-size:13px}}</style></head>
<body><div class="shell"><header class="top"><div class="brand">dopOS</div><div class="clock" id="clock"></div><div class="tools" aria-label="Local tool status"><span id="tool-docker">Docker</span><span id="tool-github">GitHub</span><span id="tool-ollama">Local AI</span></div></header><main class="frame"><section class="conversation"><div class="thread" id="thread"><div class="empty">Ask dopOS about this machine. It will create a safe plan and wait for your decision.</div></div><form class="composer" onsubmit="submitWork(event)"><span aria-hidden="true">＋</span><textarea id="request" aria-label="Ask dopOS anything" placeholder="Ask dopOS anything"></textarea><button class="send" aria-label="Send request">↑</button></form><div class="hint">Plans are frozen before approval. Local Qwen explains plans; it cannot select actions.</div></section><aside class="rail"><div class="rail-head"><h2>Live Work</h2><span class="pulse">⌁</span></div><div class="steps"><div class="step active"><strong>Goal</strong><small>Waiting for your request</small></div><div class="step"><strong>Plan</strong><small>Safe actions only</small></div><div class="step"><strong>Build</strong><small>Approval required</small></div><div class="step"><strong>Test</strong><small>Evidence captured</small></div><div class="step"><strong>Verify</strong><small>Diary updated</small></div></div><div class="side-section"><h3>Recent work</h3><div id="recent" class="empty">No work yet.</div></div><div class="side-section"><h3>Diary</h3><div id="diary" class="empty">No activity yet.</div></div></aside></main></div>
<script>
const api=async(path,body)=>{let r=await fetch(path,{method:body!==undefined?'POST':'GET',headers:{'Content-Type':'application/json'},body:body!==undefined?JSON.stringify(body):undefined});let x=await r.json();if(!r.ok)throw Error(x.error);return x};let current;
function escape(v){let d=document.createElement('div');d.textContent=v;return d.innerHTML}
function clock(){document.querySelector('#clock').textContent=new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date())}clock();setInterval(clock,30000);
function setStep(n){[...document.querySelectorAll('.step')].forEach((e,i)=>e.classList.toggle('active',i<=n))}
async function loadTools(){try{let tools=await api('/tools/status');for(let [name,value] of Object.entries(tools)){let element=document.querySelector(`#tool-${name}`);if(!element)continue;let available=value.available&&value.ok!==false;element.classList.toggle('status-off',!available);element.title=available?'Available locally':(value.error||value.reason||'Unavailable locally')}}catch{document.querySelectorAll('.tools span').forEach(e=>e.classList.add('status-off'))}}
async function loadControls(){try{let state=await api('/controls/kill-switch');let control=document.querySelector('#control-status');if(!control){control=document.createElement('button');control.id='control-status';control.className='button';control.style.padding='5px 9px';control.style.fontSize='12px';document.querySelector('.tools').append(control)}let paused=state.kill_switch==='on';control.textContent=paused?'Execution paused — Resume':'Safety ready';control.classList.toggle('danger',paused);control.title=paused?'Execution is blocked. Click to resume explicitly.':'Safe actions require your approval.';control.onclick=paused?async()=>{await api('/controls/kill-switch',{enabled:false});loadControls()}:null}catch{}}
function controls(){return '<div class="buttons"><button class="button primary" onclick="approve()">Approve</button><button class="button" onclick="reject()">Reject</button><button class="button danger" onclick="stop()">Stop</button></div>'}
function renderPlan(plan,title='Ready to execute plan'){current=plan;thread.innerHTML=`<div class="agent"><div class="orb"></div><div><div><span class="label">dopOS</span><span class="time">just now</span></div><p class="explain">${escape(plan.explanation)}</p><div class="plan"><h3>${title}</h3><p>This plan is frozen. It contains only local, read-only checks.</p><div class="actions">${plan.actions.map(a=>`<span>${escape(a)}</span>`).join('')}</div>${controls()}</div></div></div>`;setStep(1);loadDiary();loadRecent()}
function formatResults(results){return results.map(entry=>{let result=entry.result;if(entry.action==='status.summary')return `<div><strong>Host records</strong><p>${result.work_items} work items · ${result.plans} plans · ${result.audit_events} audit events</p></div>`;if(entry.action==='docker.status'){let value=result.containers||result.error||result.reason||'No Docker details returned.';return `<div><strong>Docker status</strong><pre>${escape(value)}</pre></div>`}if(entry.action==='quality.status'){let checks=result.checks||[];return `<div><strong>Local quality checks</strong><p>${result.ok?'All fixed checks passed.':'One or more checks need attention.'}</p><div class="actions">${checks.map(c=>`<span>${escape(c.name)} · ${c.passed?'passed':'failed'}</span>`).join('')}</div></div>`}if(entry.action==='backup.create')return `<div><strong>Local backup created</strong><p>${escape(result.path)} · audit chain ${result.audit_chain_valid?'verified':'needs review'}</p></div>`;if(entry.action==='backup.verify'){let checks=result.backups||[];return `<div><strong>Recovery backups</strong><p>${escape(result.message)}</p><div class="actions">${checks.map(c=>`<span>${escape(c.name)} · ${c.ok?'verified':'needs review'}</span>`).join('')}</div></div>`}if(entry.action==='diary.preview')return '<div><strong>Diary updated</strong><p>The approved run and its evidence have been recorded.</p></div>';return `<div><strong>${escape(entry.action)}</strong><p>${escape(JSON.stringify(result))}</p></div>`}).join('')}
async function submitWork(e){e.preventDefault();let text=request.value.trim();if(!text)return;thread.innerHTML=`<div class="message user">${escape(text)}</div><div class="agent"><div class="orb"></div><div><span class="label">dopOS</span><p class="explain">Preparing the smallest safe plan…</p></div></div>`;setStep(0);try{let item=await api('/work-items',{title:text.slice(0,80),request:text});renderPlan(await api('/plans/from-request',{work_item_id:item.id}));request.value=''}catch(err){thread.innerHTML+=`<div class="plan">${escape(err.message)}</div>`}}
async function approve(){try{await api(`/plans/${current.id}/approve`,{});setStep(2);let done=await api(`/plans/${current.id}/execute`,{});thread.innerHTML+=`<div class="plan"><h3>Completed</h3><p>The approved local checks finished successfully.</p><div class="results">${formatResults(done.results)}</div></div>`;setStep(4);loadDiary();loadRecent()}catch(err){thread.innerHTML+=`<div class="plan">${escape(err.message)}</div>`}}
async function reject(){await api(`/plans/${current.id}/reject`,{});thread.innerHTML+=`<div class="plan"><h3>Plan rejected</h3><p>No action was run.</p></div>`;loadDiary();loadRecent()}
async function stop(){await api('/controls/kill-switch',{enabled:true});thread.innerHTML+=`<div class="plan"><h3>Stop control enabled</h3><p>Execution is blocked until it is explicitly resumed.</p></div>`;loadDiary();loadControls()}
async function loadRecent(){try{let items=await api('/work-items');recent.innerHTML=items.slice(0,5).map(item=>`<button class="history-item" onclick="openWork(${item.id})"><strong>${escape(item.title)}</strong><small>${escape(item.plan?.state||'draft')}</small></button>`).join('')||'<div class="empty">No work yet.</div>'}catch{}}
async function openWork(id){try{let item=await api(`/work-items/${id}`);let plan=item.plan;if(!plan){thread.innerHTML=`<div class="plan"><h3>${escape(item.title)}</h3><p>${escape(item.request)}</p><p>No plan has been created yet.</p></div>`;return}if(plan.state==='awaiting_approval'){renderPlan(plan,'Saved plan');return}current=plan;let outcome=plan.state==='completed'?`<h3>Completed</h3><p>Recorded result from the approved run.</p><div class="results">${formatResults(plan.results||[])}</div>`:`<p>This plan is ${escape(plan.state)}.</p>`;thread.innerHTML=`<div class="message user">${escape(item.request)}</div><div class="agent"><div class="orb"></div><div><span class="label">dopOS</span><p class="explain">${escape(plan.explanation)}</p><div class="plan"><h3>Saved plan</h3><div class="actions">${plan.actions.map(a=>`<span>${escape(a)}</span>`).join('')}</div>${outcome}</div></div></div>`;setStep(plan.state==='completed'?4:1)}catch(err){thread.innerHTML=`<div class="plan">${escape(err.message)}</div>`}}
async function loadDiary(){try{let events=await api('/journal');diary.innerHTML=events.slice(-6).reverse().map(e=>`<div class="event">${escape(e.summary)}<time>${new Date(e.created_at).toLocaleString()}${e.detail?` · ${escape(e.detail)}`:''}</time></div>`).join('')||'<div class="empty">No activity yet.</div>'}catch{}}
loadTools();loadControls();loadRecent();
</script></body></html>'''
